<?php require_admin();$id=(int)($_GET['id']??0);$row=db_one('SELECT c.*,ca.category_name,s.name student_name,s.student_id,s.email FROM complaints c JOIN categories ca ON ca.id=c.category_id JOIN students s ON s.id=c.student_id WHERE c.id=?','i',[$id]);if(!$row){flash('danger','Complaint not found.');redirect('admin/complaints.php');}$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$newStatus=$_POST['status']??'';$remark=trim($_POST['remark']??'');if(!in_array($newStatus,['Pending','In Progress','Resolved','Closed','Rejected'],true))$errors[]='Select a valid status.';if($remark==='')$errors[]='Add a remark to explain the update.';if(!$errors){$stmt=db()->prepare('UPDATE complaints SET status=? WHERE id=?');$stmt->bind_param('si',$newStatus,$id);$stmt->execute();$adminId=admin()['id'];$stmt=db()->prepare('INSERT INTO remarks (complaint_id,admin_id,remark) VALUES (?,?,?)');$stmt->bind_param('iis',$id,$adminId,$remark);$stmt->execute();flash('success','Complaint updated and remark added.');redirect('admin/complaint.php?id='.$id);}}$remarks=db_all('SELECT r.*,a.name admin_name FROM remarks r JOIN admins a ON a.id=r.admin_id WHERE r.complaint_id=? ORDER BY r.created_at DESC','i',[$id]);$pageTitle='Manage Complaint';require_once __DIR__.'/../includes/header.php'; ?>
<div class="row g-4"><div class="col-lg-3"><?php require __DIR__.'/_sidebar.php'; ?></div><div class="col-lg-9"><div class="dashboard-header mb-4 d-flex justify-content-between align-items-start flex-wrap gap-3"><div><div class="complaint-id mb-2"><?=e($row['complaint_id'])?></div><h1 class="section-title mb-1"><?=e($row['title'])?></h1><div class="small-muted">Submitted by <?=e($row['student_name'])?> (<?=e($row['student_id'])?>)</div></div><span class="badge-soft <?=e(status_class($row['status']))?>"><?=e($row['status'])?></span></div><?php if($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $item): ?><li><?=e($item)?></li><?php endforeach;?></ul></div><?php endif; ?><div class="row g-4"><div class="col-xl-7"><div class="card h-100"><div class="card-body"><div class="row g-4 mb-4"><div class="col-sm-4"><div class="detail-label">Category</div><div class="detail-value"><?=e($row['category_name'])?></div></div><div class="col-sm-4"><div class="detail-label">Priority</div><div class="detail-value <?=e(priority_class($row['priority']))?>"><?=e($row['priority'])?></div></div><div class="col-sm-4"><div class="detail-label">Student email</div><div class="detail-value small"><?=e($row['email'])?></div></div></div><div class="detail-label mb-2">Description</div><p style="white-space:pre-line"><?=e($row['description'])?></p><?php if($row['attachment']): ?><a class="btn btn-sm btn-outline-primary" target="_blank" href="<?=e(url('uploads/'.$row['attachment']))?>">View attachment</a><?php endif;?></div></div></div><div class="col-xl-5"><div class="card"><div class="card-header"><strong>Update complaint</strong></div><div class="card-body"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label class="form-label">New status</label><select class="form-select mb-3" name="status"><?php foreach(['Pending','In Progress','Resolved','Closed','Rejected'] as $v): ?><option <?=($row['status']===$v)?'selected':''?>><?=e($v)?></option><?php endforeach;?></select><label class="form-label">Administrator remark</label><textarea class="form-control" name="remark" rows="5" required placeholder="Explain the action or next step."></textarea><button class="btn btn-primary w-100 mt-3">Save update</button></form></div></div></div></div><div class="card mt-4"><div class="card-header"><strong>Remark history</strong></div><div class="card-body"><?php if(!$remarks): ?><div class="empty-state py-4">No remarks yet.</div><?php else: ?><div class="timeline"><?php foreach($remarks as $remark): ?><div class="timeline-item"><div class="fw-semibold"><?=e($remark['admin_name'])?></div><div class="small-muted mb-2"><?=e(date('d M Y, h:i A',strtotime($remark['created_at'])))?></div><div style="white-space:pre-line"><?=e($remark['remark'])?></div></div><?php endforeach;?></div><?php endif;?></div></div></div></div>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
